args.command:
cd ~/captures; python3 - <<'EOF'
from PIL import Image
for f in ['wrist_001.png','wrist_003.png','wrist_004.png']:
    im=Image.open(f).convert('L'); w,h=im.size; px=im.load()
    sx=sy=n=0
    for y in range(380,h):
        for x in range(w):
            if px[x,y]<70: sx+=x; sy+=y; n+=1
    print(f, 'centroid x=%.1f y=%.1f n=%d'%(sx/n,sy/n,n) if n else 'none')
EOF

